from pathlib import Path

lines = Path("prog.pw9").read_text().splitlines()
prog = []
for line in lines:
    line = line.split(";", 1)[0].strip()
    if line:
        prog.append(line.split())

regs = {"a": 0, "b": 0, "c": 0, "d": 0}
MOD = 65536


def val(x):
    return regs[x] if x in regs else int(x)


outputs = []
ip = 0
count = 0
n = len(prog)
steps = 0
while 0 <= ip < n:
    steps += 1
    if steps > 100_000_000:
        raise SystemExit("too many steps")
    op, *args = prog[ip]
    count += 1
    if op == "set":
        r, x = args
        regs[r] = val(x) % MOD
        ip += 1
    elif op == "add":
        r, x = args
        regs[r] = (regs[r] + val(x)) % MOD
        ip += 1
    elif op == "mul":
        r, x = args
        regs[r] = (regs[r] * val(x)) % MOD
        ip += 1
    elif op == "mod":
        r, x = args
        v = val(x)
        if v > 0:
            regs[r] = regs[r] % v
        ip += 1
    elif op == "dec":
        (r,) = args
        regs[r] = max(regs[r] - 1, 0)
        ip += 1
    elif op == "jnz":
        x, k = args
        if val(x) != 0:
            ip += val(k)
        else:
            ip += 1
    elif op == "skp":
        x, y = args
        if val(x) < val(y):
            ip += 2
        else:
            ip += 1
    elif op == "out":
        (x,) = args
        outputs.append(val(x))
        ip += 1
    else:
        raise SystemExit(f"bad op {op}")

print("sum", sum(outputs), "count", count, "n_out", len(outputs))
print("answer", sum(outputs), count)

