        elif op=='add': regs[ar[0]]=(regs[ar[0]]+get(ar[1],regs))%M
        elif op=='mul': regs[ar[0]]=(regs[ar[0]]*get(ar[1],regs))%M
        elif op=='mod':
            d=get(ar[1],regs)
            if d>0: regs[ar[0]]%=d
        elif op=='dec': regs[ar[0]]=max(0,regs[ar[0]]-1)
